  "equipMoney.unitNote": "A unit's revenue is its item's revenue shared by the days each unit was owned in the period, so a unit bought mid-period gets a smaller share. Hire-in stays on the item.",
  "equipMoney.howProfit": "How it's counted: revenue = rental lines of accepted quotes dated in the period (the gig's start date), after discounts, excl. VAT; a set's revenue is shared out to its contents by their day prices; lines typed by hand count as \"not linked to an item\". Costs: depreciation in the period (straight line over the write-off period, 60 months unless set), repairs not charged to the client, inspection costs, hire-in for the item and losses at replacement value (less any payout). Labour is not shared out to equipment. In euros.",
  "equipMoney.howPayback": "How it's counted: revenue since each purchase (up to today) against the purchase cost. A unit gets an equal share of its item's revenue on each day it was owned. When it hasn't paid back yet, the date is where the pace of the last 12 months (or since purchase, if shorter) would take it.",
  "equipMoney.howBuy": "How it's counted: what subrentals of each item cost over the last 12 months (confirmed or returned; a linked expense replaces the supplier's price), against buying as many as you hired at once, at the item's cost price (else its replacement value). \"Pays back in\" is that cost ÷ the monthly hire-in spend.",
